    return scheme


@pure_lazy
def _permission_shape_without_catalog(
    model_cls: type[DatabaseObjectRow],
) -> PermissionShape | None:
    """Return permission metadata for one model without building a global catalog."""
    if _is_permission_bootstrap_model_lazy(model_cls):
        return PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    try:
        scheme = get_permission_scheme(model_cls)
    except RuntimeError:
        return PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    visibility_fields = tuple(get_visibility_fields(model_cls))
    return PermissionShape(
        model_cls=model_cls,
        scheme=scheme,
        scheme_factory=type(scheme) if scheme is not None else None,
        visibility_fields=visibility_fields,
    )


@pure_lazy
def _permission_context_for_shape(
    txn: object,
    permission_shape: PermissionShape,
) -> tuple[type[ResolvedSessionContext] | None, ObjectServerRef[ResolvedSessionContext] | None]:
    scheme = permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None, None
    context_ref = getattr(txn, "_permission_session_context_ref", None)
    if context_ref is None:
        return None, None
    if not isinstance(context_ref, ObjectServerRef):
        msg = "Permission context authority must be an ObjectServerRef"
        raise TypeError(msg)
    context_type = context_ref.value_type
    if not isinstance(context_type, type) or not issubclass(context_type, ResolvedSessionContext):
        msg = "Permission context authority must declare a ResolvedSessionContext model type"
        raise TypeError(msg)
    return context_type, context_ref


@pure_lazy
def permission_planning_input_for_model(
    txn: object,
    model_cls: type[DatabaseObjectRow],
) -> PermissionPlanningInput:
    """Resolve permission facts, using the transaction catalog only when needed."""
    permission_shape = _permission_shape_without_catalog(model_cls)
    if permission_shape is not None:
        context_type, context_ref = _permission_context_for_shape(txn, permission_shape)
        return PermissionPlanningInput(
            model_cls=model_cls,
            permission_shape=permission_shape,
            session_id_source=_require_session_id_source(cast("WriteTransactionLazyMixin", txn)),
            provider_authority_resolved=model_cls in getattr(txn, "_provider_authority_models", ()),
            context_type=context_type,
            context_ref=context_ref,
        )
    planning_catalog = getattr(txn, "planning_catalog", None)
    if planning_catalog is None:
        msg = "Lazy write permission planning requires a transaction planning_catalog snapshot."
        raise RuntimeError(msg)
    permission_shape = planning_catalog.permission_for_model(model_cls)
    if permission_shape is None:
        permission_shape = PermissionShape(
            model_cls=model_cls,
            scheme=None,
            scheme_factory=None,
            visibility_fields=(),
        )
    context_type, context_ref = _permission_context_for_shape(txn, permission_shape)
    return PermissionPlanningInput(
        model_cls=model_cls,
        permission_shape=permission_shape,
        session_id_source=_require_session_id_source(cast("WriteTransactionLazyMixin", txn)),
        provider_authority_resolved=model_cls in getattr(txn, "_provider_authority_models", ()),
        context_type=context_type,
        context_ref=context_ref,
    )


