@pure_lazy
def _literal_lazy_result_value[T](
    source: LazyResult[T],
    *,
    context: str,
    _type_marker: type[T] | None = None,
) -> T:
    del _type_marker
    shape = inspect_server_value_shape_for_planning(source, site=context)
    if shape.symbolic_ref_id is not None:
        msg = f"{context} requires a literal LazyResult, got ref {shape.symbolic_ref_id!r}"
        raise RuntimeError(msg)
    if shape.has_literal_value:
        return cast(T, shape.literal_value)
    if source._state is LazyState.ERROR:
        assert source._error is not None
        raise source._error
    msg = f"{context} requires a concrete literal LazyResult"
    raise RuntimeError(msg)


@pure_lazy
def _ensure_permission_context_plan_ref(
    txn: WriteTransactionLazyMixin,
    permission_context: LazyResult[object],
) -> ServerPlanRefId:
    shape = inspect_server_value_shape_for_planning(
        permission_context,
        site="Permission context lazy result",
    )
    if shape.symbolic_ref_id is not None:
        return ServerPlanRefId(shape.symbolic_ref_id)

    plan = txn._get_transaction_plan_lazy()
    ref_id = ServerPlanRefId(plan._next_ref())
    plan.add_step(
        ReturnValueStep(
            ref_id,
            _literal_lazy_result_value(
                permission_context,
                context="permission context plan ref",
            ),
        ),
    )
    return ref_id


@pure_lazy
