    return _ensure_permission_context_plan_ref(txn, permission_context)


@pure_lazy
def _require_session_id_source(
    txn: WriteTransactionLazyMixin,
) -> SessionIdSource:
    session_id_source_fn = getattr(txn, "_session_id_source_lazy", None)
    session_id_source = session_id_source_fn() if callable(session_id_source_fn) else getattr(txn, "_session_id", None)
    # ``LazySessionSqlSource`` is accepted alongside the value and reference
    # shapes because a write under ``authenticated_session_lazy`` has no other
    # shape to offer. Rejecting it here is what the write path did until this
    # ladder tried it, and the refusal was indistinguishable from "the caller
    # forgot to set a session" -- the same message for a plan whose session is
    # perfectly well specified, only as a query.
    if isinstance(session_id_source, SessionId | LazyResult | ScalarServerRef | LazySessionSqlSource):
        return session_id_source
    msg = "Lazy write permission checks require an explicit session_id."
    raise RuntimeError(msg)


@pure_lazy
def _enqueue_permission_step[T](
    txn: ReadTransactionLazyMixin,
    step: ServerPlanStep[T],
) -> LazyResult[T]:
    if _in_lazy_context() or _supports_serverplan_permission_intents(txn):
        return txn._add_intent(step)
    msg = "Lazy permission step requires active lazy context or plan-intent support."
    raise RuntimeError(msg)


@pure_lazy
def assert_permission_allowed_lazy(
    txn: ReadTransactionLazyMixin,
    allowed: LazyResult[bool],
    error: Exception,
) -> LazyResult[None]:
    """Enqueue a permission guard for a lazy boolean predicate."""
    shape = inspect_server_value_shape_for_planning(
        allowed,
        site="Permission assertion predicate",
    )
    if shape.symbolic_ref_id is None:
        if allowed._state is LazyState.PENDING:
            msg = "Permission assertion requires an explicit ServerPlan predicate ref"
            raise RuntimeError(msg)
        if _literal_lazy_result_value(allowed, context="permission assertion"):
            return LazyResult.of(None)
        raise error

    plan = txn._get_transaction_plan_lazy()
    predicate_ref = ServerRefs.from_ref_id(shape.symbolic_ref_id, variant="scalar", type_hint=bool)
    step = AssertStep(
        ref_id=ServerPlanRefId(plan._next_ref()),
        predicate_ref=predicate_ref,
        error=error,
    )
    return _enqueue_permission_step(txn, step)


def run_table_write_permission_check_after_session_context(
    txn: ReadTransaction | WriteTransaction,
    model_cls: type[DatabaseObjectRow],
    scheme: object,
    session_id: SessionId,
    resolved: ResolvedSessionContext,
) -> None:
    """Run table-level write permission using a materialized session context (executor/runtime)."""
    if isinstance(scheme, GraphInheritedPermissionScheme):
        # Graph-inherited table writes are allowed; object-level checks enforce graph access.
        return
    if not isinstance(scheme, PermissionScheme):
        msg = f"Unsupported runtime table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    context = _build_table_write_permission_context(
        txn,
        scheme,
        session_id,
        resolved,
    )
    dispatch_write_permission_operation_with_scheme(
        RuntimeWritePermissionSpec(
            model_cls=model_cls,
            operation="table_write",
            permission_scheme_cls=type(scheme),
        ),
        scheme,
        context,
    )


def run_object_write_permission_check_after_session_context(
    txn: ReadTransaction | WriteTransaction,
    model_cls: type[DatabaseObjectRow],
    obj: DatabaseObjectRow,
    session_id: SessionId,
    resolved: ResolvedSessionContext,
) -> None:
    """Run object-level write permission using a materialized session context."""
    del txn, session_id
    scheme = _get_runtime_object_level_permission_scheme(model_cls)
    if scheme is None:
        return
    context = _build_object_write_permission_context(scheme, resolved)
    dispatch_write_permission_operation_with_scheme(
        RuntimeWritePermissionSpec(
            model_cls=model_cls,
            operation="object_write",
            permission_scheme_cls=type(scheme),
        ),
        scheme,
        context,
        instance=obj,
    )


@pure_lazy
def get_cached_resolved_session_context(
    session_id: SessionId,
    txn: ReadTransaction,
) -> tuple[bool, ResolvedSessionContext | None]:
    """Return a prevalidated session context when one is available without I/O.

    ``@pure_lazy`` states what the docstring already claimed: reachable from
    lazy permission compilation, and reading attributes the transaction set
    during validation rather than going to the database.
    """
    session_type = getattr(txn, "_nera_validated_session_type", None)
    if session_type not in {"system", "user"}:
        return False, None
    raw_user_id = getattr(txn, "_nera_validated_session_user_id", None)
    user_id = None if raw_user_id is None else UserId(str(raw_user_id))
    has_system_authority = _has_validated_system_authority(txn)
    is_system_session = session_id.is_schema_session() or has_system_authority
    return True, ResolvedSessionContext(
        session_id=session_id,
        user_id=user_id,
        effective_user_id=None,
        session_type="system" if is_system_session else "user",
        is_system_session=is_system_session,
    )


@pure_lazy
def get_cached_validated_session_user_id(
    session_id: SessionId,
    txn: ReadTransaction,
) -> tuple[bool, UserId | None]:
    """Return a cached validated user id when available without I/O.

    ``@pure_lazy`` for the same reason as the context reader it delegates to.
    """
    cached, context = get_cached_resolved_session_context(session_id, txn)
    if not cached or context is None:
        return False, None
    return True, context.user_id


def check_write_permission(
    model_cls: type[DatabaseObjectRow],
    session_id: str,
    txn: ReadTransaction,
) -> None:
    """Compatibility boundary for eager no-I/O fallback paths."""
    _check_write_permission(model_cls, SessionId(session_id), txn)


@pure_lazy
def _has_lazy_read_semantics(txn: object) -> bool:
    return isinstance(txn, ReadTransaction) or hasattr(txn, "base_read_transaction")


@pure_lazy
def _has_validated_system_authority(
    txn: object,
    model_cls: type[DatabaseObjectRow] | None = None,
) -> bool:
    """Return whether admission bound non-transferable authority to this transaction."""
    from l1300_session.system_authority_service import ValidatedSystemAuthority

    authority = getattr(txn, "_validated_system_authority", None)
    if isinstance(authority, ValidatedSystemAuthority) or getattr(txn, "_system_authority_planning_only", False) is True:
        return True
    if model_cls is None or getattr(txn, "_capability_lifecycle_admin_authority", None) is None:
        return False
    return model_cls.__module__ == "l6500_evidence.capability_models" and model_cls.__name__ in {
        "CapabilitySecurityEvent",
        "CapabilityTokenFamily",
        "CapabilityTokenIssued",
        "CapabilityTokenRevocation",
        "CapabilityTokenUsage",
    }


@pure_lazy
def check_write_permission_lazy(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
) -> LazyResult[None]:
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model_lazy(model_cls) or _has_validated_system_authority(txn, model_cls):
        return LazyResult.of(None)
    if not _has_lazy_read_semantics(txn):
        msg = "Lazy write permission checks require a transaction with read semantics."
        raise TypeError(msg)
    scheme = permission_input.permission_shape.scheme
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if literal_session_id is not None and is_system_or_schema_session(
        session_id_to_str(literal_session_id),
    ):
        return LazyResult.of(None)
    if not _supports_serverplan_permission_intents(txn):
        msg = "Lazy write permission checks require lazy-plan transaction support."
        raise RuntimeError(msg)
    if scheme is None:
        return LazyResult.of(None)
    if not isinstance(scheme, PermissionScheme):
        msg = f"Unsupported lazy table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    if isinstance(scheme, GraphInheritedPermissionScheme):
        return LazyResult.of(None)
    decision = scheme.get_table_write_permission_decision(model_cls, literal_session_id)
    if decision.allowed:
        return LazyResult.of(None)
    context_ref = (
        _bound_permission_context_ref(
            permission_input,
            site="Table write permission context",
        )
        if permission_input.context_ref is not None
        else _resolve_scheme_permission_context_ref(
            txn,
            cast("PermissionScheme[object]", scheme),
            session_id_source,
        )
    )
    return _queue_table_write_permission_guard_intent(
        txn,
        context_ref,
        model_cls,
    )


@pure_lazy
def upsert_requires_action_authority(permission_input: PermissionPlanningInput) -> bool:
    """Select guarded SQL rowset compilation for actors subject to write policies."""
    if object_write_permission_bypassed_by_session(permission_input):
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme):
        raise PermissionCompilationError("Upsert requires a registered permission scheme")
    return any(scheme.get_query_permission_plan(permission_input.model_cls, action=action).filter_rows for action in ("insert", "update"))


@pure_lazy
def check_insert_permission_lazy(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
    instance: LazyResult[DatabaseObjectRow | None],
    source_ref: ServerPlanRefId | None = None,
    source_is_sequence: bool = False,
) -> LazyResult[None]:
    """Check the proposed row using its insert policy, not legacy write flags."""
    from impl.common.l2070_server_plan.steps.insert_permission import InsertPermissionAssertionStep
    from l1000_schema.schema_def import DatabaseObjectRow

    scheme = permission_input.permission_shape.scheme
    proposed_row = _literal_lazy_result_value(
        instance,
        context="check_insert_permission_lazy instance",
    )
    assert proposed_row is None or isinstance(proposed_row, permission_input.model_cls)
    if proposed_row is not None and isinstance(scheme, PermissionScheme) and scheme.requires_validated_insert_models():
        permission_input.model_cls.model_validate(proposed_row.model_dump(mode="python"))
    if (
        object_write_permission_bypassed_by_session(permission_input)
        or _is_permission_bootstrap_model_lazy(permission_input.model_cls)
        or _has_validated_system_authority(txn, permission_input.model_cls)
    ):
        return LazyResult.of(None)
    if not isinstance(scheme, PermissionScheme):
        raise PermissionCompilationError("Insert authorization requires a registered permission scheme")
    policy = scheme.get_query_permission_plan(permission_input.model_cls, action="insert")
    if not policy.filter_rows:
        return LazyResult.of(None)
    assert proposed_row is None or isinstance(proposed_row, DatabaseObjectRow)
    if not _has_lazy_read_semantics(txn) or not _supports_serverplan_permission_intents(txn):
        raise RuntimeError("Insert authorization requires a transaction-backed lazy plan")
    plan = txn._get_transaction_plan_lazy()
    permission_context_ref = (
        _bound_permission_context_ref(
            permission_input,
            site="Insert permission context",
        )
        if permission_input.context_ref is not None
        else None
    )
    return _enqueue_permission_step(
        txn,
        InsertPermissionAssertionStep(
            plan._next_ref(),
            permission_input.model_cls,
            proposed_row,
            source_ref=source_ref,
            source_is_sequence=source_is_sequence,
            permission_context_ref=permission_context_ref,
            permission_context_type=permission_input.context_type,
        ),
    )


@pure_lazy
def check_object_write_permission_lazy[T: DatabaseObjectRow](
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
    instance: T,
) -> LazyResult[T]:
    model_cls = cast("type[T]", permission_input.model_cls)
    scheme = _get_object_level_permission_scheme(permission_input)
    if scheme is None or _has_validated_system_authority(txn, model_cls):
        return LazyResult.of(instance)
    if not _has_lazy_read_semantics(txn):
        msg = "Lazy object write permission checks require a transaction with read semantics."
        raise TypeError(msg)
    if not _supports_serverplan_permission_intents(txn):
        msg = "Lazy object write permission checks require lazy-plan transaction support."
        raise RuntimeError(msg)
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if (
        literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(model_cls, action="write").filter_reserved_sessions
    ):
        return LazyResult.of(instance)
    permission_context_ref = get_object_write_permission_context_ref(txn, permission_input)
    permission_context_type = permission_input.context_type
    if not isinstance(permission_context_ref, ServerPlanRefId):
        msg = "Lazy object write permission checks require a branded deferred permission context ref."
        raise RuntimeError(msg)
    plan = txn._get_transaction_plan_lazy()
    step = lazy_runtime.ReturnLiteralAfterObjectWritePermissionCheckStep(
        ref_id=plan._next_ref(),
        instance=instance,
        permission_context_ref=permission_context_ref,
        permission_context_type=permission_context_type,
        model_cls=model_cls,
    )
    return cast("LazyResult[T]", _enqueue_permission_step(txn, cast("ServerPlanStep[DatabaseObjectRow]", step)))


def _build_table_write_permission_context(
    txn: ReadTransaction,
    scheme: object,
    session_id: SessionId,
    session_context: ResolvedSessionContext,
) -> object:
    from l4000_permissions.multi_field_ownership_scheme import (
        MultiFieldOwnershipContext,
        MultiFieldOwnershipScheme,
    )
    from l4000_permissions.rbac_scheme import RBACContext, RBACScheme
    from l4000_permissions.self_ownership_scheme import (
        SelfOwnershipContext,
        SelfOwnershipScheme,
    )

    if isinstance(scheme, PermissionScheme):
        runtime_context = scheme.build_runtime_table_write_permission_context(
            txn=txn,
            session_id=session_id,
            session_context=session_context,
        )
        if runtime_context is not None:
            return runtime_context

    context: object
    if isinstance(scheme, SystemOnlyScheme):
        context = SystemPermissionContext(session_id, session_context)
    elif isinstance(scheme, NoSecurityScheme):
        context = NoSecurityContext(
            session_context.user_id,
            is_authenticated=(
                session_context.is_system_session or session_context.user_id is not None or session_context.effective_user_id is not None
            ),
            session_context=session_context,
        )
    elif isinstance(scheme, OwnershipScheme):
        context = OwnershipContext(session_context)
    elif isinstance(scheme, SelfOwnershipScheme):
        context = SelfOwnershipContext(session_context)
    elif isinstance(scheme, OwnerSharesScheme):
        context = OwnerSharesContext.from_session_context(session_context)
    elif isinstance(scheme, OwnerRoleSharesScheme):
        role_permissions = frozenset({"*"}) if session_context.is_system_session else frozenset()
        context = OwnerRoleSharesContext(session_context, role_permissions)
    elif isinstance(scheme, QueueMessagePermissionScheme):
        context = QueuePermissionContext.from_session_context(
            session_id,
            session_context,
        )
    elif isinstance(scheme, MultiFieldOwnershipScheme):
        context = MultiFieldOwnershipContext(session_context)
    elif isinstance(scheme, AssignedRoleScheme):
        context = AssignedRoleContext(session_context)
    elif isinstance(scheme, AssignedPermissionScheme):
        context = AssignedPermissionContext(session_context)
    elif isinstance(scheme, RBACScheme):
        rbac_permissions: set[str] = {"*"} if session_context.is_system_session else set()
        context = RBACContext(session_context.user_id, rbac_permissions)
    elif isinstance(scheme, GraphInheritedPermissionScheme):
        context = GraphInheritedPermissionContext(
            session_id,
            session_context,
            getattr(txn, "domain", None),
        )
    else:
        msg = f"Unsupported runtime table-write permission scheme: {type(scheme).__name__}"
        raise TypeError(msg)
    return context


def _build_object_write_permission_context(
    scheme: PermissionScheme[object],
    session_context: ResolvedSessionContext,
) -> object:
    from l4000_permissions.self_ownership_scheme import SelfOwnershipContext, SelfOwnershipScheme

    if isinstance(scheme, OwnershipScheme):
        return OwnershipContext(session_context)
    if isinstance(scheme, SelfOwnershipScheme):
        return SelfOwnershipContext(session_context)
    msg = f"Unsupported runtime object-write permission scheme: {type(scheme).__name__}"
    raise TypeError(msg)


@pure_lazy
def _queue_table_write_permission_guard_intent(
    txn: WriteTransactionLazyMixin,
    permission_context_ref: str | None,
    model_cls: type[DatabaseObjectRow],
) -> LazyResult[None]:
    plan = txn._get_transaction_plan_lazy()
    intent = lazy_runtime.TableWritePermissionGuardIntent(
        ref_id=ServerPlanRefId(plan._next_ref()),
        permission_context_ref=(None if permission_context_ref is None else ServerPlanRefId(permission_context_ref)),
        config=lazy_runtime._TableWritePermissionGuardConfig(
            model_cls=model_cls,
        ),
    )
    return _enqueue_permission_step(txn, intent)


