@pure_lazy
def object_write_permission_bypassed_by_session(
    permission_input: PermissionPlanningInput,
) -> bool:
    """Return whether object write guards are unnecessary for this session."""
    if permission_input.provider_authority_resolved:
        return True
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if literal_session_id is None or not is_system_or_schema_session(session_id_to_str(literal_session_id)):
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme):
        return True
    return not scheme.get_query_permission_plan(
        permission_input.model_cls,
        action="write",
    ).filter_reserved_sessions


@pure_lazy
def permission_scheme_requires_validated_insert_models(scheme: object) -> bool:
    """Return whether insert proposals require model revalidation."""
    return isinstance(scheme, PermissionScheme) and scheme.requires_validated_insert_models()


def is_system_only_permission_scheme(
    model_cls: type[DatabaseObjectRow],
) -> bool:
    """Return whether the model uses system-only table permissions at runtime."""
    return isinstance(get_permission_scheme(model_cls), SystemOnlyScheme)


@pure_lazy
def _bound_permission_context_ref(
    permission_input: PermissionPlanningInput,
    *,
    site: str,
) -> ServerPlanRefId:
    context_ref = permission_input.context_ref
    if context_ref is None:
        msg = f"{site} requires the bound session context authority"
        raise RuntimeError(msg)
    context_shape = inspect_server_value_shape_for_planning(
        context_ref,
        site=site,
    )
    if context_shape.symbolic_ref_id is None:
        msg = f"{site} must publish a symbolic ref"
        raise RuntimeError(msg)
    return ServerPlanRefId(context_shape.symbolic_ref_id)


@pure_lazy
def get_object_write_permission_context_ref(
    txn: WriteTransactionLazyMixin,
    permission_input: PermissionPlanningInput,
) -> ServerPlanRefId | None:
    """Return the scheme-context plan ref needed for object-level write guards."""
    scheme = _get_object_level_permission_scheme(permission_input)
    if scheme is None or not _has_lazy_read_semantics(txn):
        return None
    if not _in_lazy_context() and not _supports_serverplan_permission_intents(txn):
        return None
    session_id_source = cast("SessionIdSource", permission_input.session_id_source)
    literal_session_id = _literal_session_id_or_none(session_id_source)
    if (
        literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(permission_input.model_cls, action="write").filter_reserved_sessions
    ):
        return None
    if permission_input.context_ref is not None:
        return _bound_permission_context_ref(
            permission_input,
            site="Object write permission context",
        )
    return _resolve_scheme_permission_context_ref(
        txn,
        scheme,
        session_id_source,
    )


@pure_lazy
def _versioned_permission_domain(txn: object) -> type[VersioningDomain] | None:
    try:
        domain = getattr(txn, "domain", None)
    except RuntimeError:
        domain = None
    if domain is None:
        domain = getattr(txn, "_domain", None)
    if domain is None:
        return None
    if isinstance(domain, type) and issubclass(domain, VersioningDomain):
        return domain
    msg = f"Expected VersioningDomain type on transaction, got {type(domain).__name__}"
    raise TypeError(msg)


@pure_lazy
def _uses_sparse_historical_permission_context(txn: object) -> bool:
    revision_id = getattr(txn, "_revision_id", None)
    if revision_id is None:
        try:
            revision_id = getattr(txn, "revision_id", None)
        except RuntimeError:
            revision_id = None
    if revision_id is None:
        return False
    from l7000_versioned_schema.branch_materialization import BranchTipMaterialization

    return getattr(txn, "_branch_tip_materialization", None) is not BranchTipMaterialization.MATERIALIZED


@pure_lazy
def _permission_version_anchor_for_txn(
    txn: object,
) -> PermissionVersionAnchor | None:
    domain = _versioned_permission_domain(txn)
    if domain is None:
        return None
    return permission_version_anchor_from_txn(domain, txn)


@pure_lazy
def compile_permission_expression(
    model_cls: type[DatabaseObjectRow],
    session_id: object,
    *,
    txn: object,
    action: str = "read",
) -> SqlRenderable | None:
    """Compile the read filter for a model/session pair."""
    if _is_permission_bootstrap_model(model_cls) or _has_validated_system_authority(txn, model_cls):
        return None
    session_str = session_id_to_str(session_id)
    scheme = get_permission_scheme(model_cls)
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None
    if not isinstance(session_id, SessionId | ScalarServerRef):
        msg = (
            "Permission compilation requires a literal or scalar-ref session identity; "
            f"got {type(session_id).__name__} for {type(scheme).__name__}"
        )
        raise PermissionCompilationError(msg)
    typed_session_id = session_id
    if isinstance(typed_session_id, ScalarServerRef):
        msg = "compile_permission_expression() requires a literal SessionId"
        raise PermissionCompilationError(msg)
    if is_system_or_schema_session(session_str):
        scheme = get_permission_scheme(model_cls)
        if isinstance(scheme, OwnerSharesScheme):
            if not isinstance(txn, ReadTransaction):
                msg = f"compile_permission_expression() expected ReadTransaction, got {type(txn).__name__}"
                raise TypeError(msg)
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=get_table_name(model_cls),
                action=action,
                domain=_versioned_permission_domain(txn),
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        return None

    if txn is not None:
        if not isinstance(txn, ReadTransaction):
            msg = f"compile_permission_expression() expected ReadTransaction, got {type(txn).__name__}"
            raise TypeError(msg)
        alias = get_table_name(model_cls)
        scheme = get_permission_scheme(model_cls)
        if isinstance(scheme, GraphInheritedPermissionScheme):
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=alias,
                action=action,
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        # Keep lazy permission compilation fail-closed. If the dedicated
        # compiler cannot lower a permission expression, do not fall back to
        # the generic Expression compiler, which can leak raw permission helper
        # functions like GRAPH_INHERITED_CHECK() into SQL.
        scheme = get_permission_scheme(model_cls)
        if scheme is None:
            return None
        return lazy_runtime.compile_permission_where_for_scheme(
            model_cls,
            scheme,
            typed_session_id,
            table_alias=alias,
            action=action,
            domain=_versioned_permission_domain(txn),
            version_anchor=_permission_version_anchor_for_txn(txn),
        )

    scheme = get_permission_scheme(model_cls)
    if scheme is None:
        return None
    msg = (
        "compile_permission_expression() requires a transaction-backed permission compiler; "
        "refusing to lower permission expressions through the generic expression compiler"
    )
    raise PermissionCompilationError(msg)


@pure_lazy
def _compile_permission_from_bound_context(
    permission_input: PermissionPlanningInput,
    scheme: PermissionScheme[Any, Any, Any, Any],
    *,
    txn: object,
    action: str,
    table_alias: str,
) -> SqlRenderable:
    context_type = permission_input.context_type
    context_ref = permission_input.context_ref
    if context_type is None or context_ref is None:
        msg = "Permission compilation requires the transaction-bound session context authority"
        raise PermissionCompilationError(msg)
    context_shape = inspect_server_value_shape_for_planning(
        context_ref,
        site="Permission expression context",
    )
    if context_shape.symbolic_ref_id is None:
        msg = "Permission expression context must publish a symbolic ref"
        raise PermissionCompilationError(msg)
    return lazy_runtime.compile_permission_where_for_scheme_with_context_sql(
        permission_input.model_cls,
        scheme,
        context_type,
        context_shape.symbolic_ref_id,
        table_alias,
        action=action,
        domain=_versioned_permission_domain(txn),
        version_anchor=_permission_version_anchor_for_txn(txn),
    )


@pure_lazy
def compile_permission_expression_from_input(
    permission_input: PermissionPlanningInput,
    *,
    txn: object,
    action: str = "read",
) -> SqlRenderable | None:
    """Compile a permission expression from resolved planning metadata."""
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model(model_cls) or _has_validated_system_authority(txn, model_cls):
        return None
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return None
    literal_session_id = _literal_session_id_or_none(
        cast("SessionIdSource", permission_input.session_id_source),
    )
    if (
        permission_input.context_ref is None
        and literal_session_id is not None
        and is_system_or_schema_session(session_id_to_str(literal_session_id))
        and not scheme.get_query_permission_plan(model_cls, action=action).filter_reserved_sessions
    ):
        return None
    if permission_input.context_ref is not None:
        if not _has_lazy_read_semantics(txn):
            msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
            raise TypeError(msg)
        return _compile_permission_from_bound_context(
            permission_input,
            scheme,
            txn=txn,
            action=action,
            table_alias=str(get_table_name(model_cls)),
        )

    session_id = permission_input.session_id_source
    session_str = session_id_to_str(session_id)
    typed_session_id = session_id if isinstance(session_id, SessionId | ScalarServerRef) else SessionId(session_str)
    if isinstance(typed_session_id, ScalarServerRef):
        msg = "compile_permission_expression_from_input() requires a literal SessionId"
        raise PermissionCompilationError(msg)
    if is_system_or_schema_session(session_str):
        if isinstance(scheme, OwnerSharesScheme):
            if not _has_lazy_read_semantics(txn):
                msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
                raise TypeError(msg)
            return lazy_runtime.compile_permission_where_for_scheme(
                model_cls,
                scheme,
                typed_session_id,
                table_alias=get_table_name(model_cls),
                action=action,
                version_anchor=_permission_version_anchor_for_txn(txn),
            )
        return None

    if not _has_lazy_read_semantics(txn):
        msg = f"compile_permission_expression_from_input() expected ReadTransaction, got {type(txn).__name__}"
        raise TypeError(msg)
    return lazy_runtime.compile_permission_where_for_scheme(
        model_cls,
        scheme,
        typed_session_id,
        table_alias=get_table_name(model_cls),
        action=action,
        version_anchor=_permission_version_anchor_for_txn(txn),
        user_id=_validated_session_user_id_or_none(typed_session_id, txn),
    )


@pure_lazy
def _validated_session_user_id_or_none(
    session_id: SessionId,
    txn: object,
) -> UserId | None:
    """Return the session's user if this transaction already validated it.

    Only a *validated* result counts. The distinction matters: a value read
    from somewhere the session was merely mentioned would be a permission
    decision made on unchecked input, which is the one thing a permission
    predicate may not be built from.

    Marked ``@pure_lazy`` because it is reached from permission compilation,
    which is a lazy call chain, and it does no I/O -- it reads a cache the
    transaction has already populated, returning ``None`` when it has not. The
    marker distinguishes that from the thing the rule is looking for, which is
    an eager lookup hiding behind a lazy caller.
    """
    if not isinstance(txn, ReadTransaction):
        return None
    cached, user_id = get_cached_validated_session_user_id(session_id, txn)
    return user_id if cached else None


def permission_filter_defers_the_session_user(
    permission_input: PermissionPlanningInput,
    *,
    txn: object,
    action: str = "read",
) -> bool:
    """Return whether the filter just built still has to look the user up.

    True means the predicate contains ``SELECT user_id FROM sys_sessions ...``
    because nothing here knew the answer yet, and that a later phase which does
    know it may rebind the predicate rather than let the database repeat the
    work. False means either that no user is involved or that one was bound, and
    in both cases the predicate is final.

    Deliberately a separate question from compiling the filter, rather than a
    second return value: the answer is about what a *later* phase is allowed to
    do, and only the plan-backed caller has any use for it.
    """
    model_cls = permission_input.model_cls
    if _is_permission_bootstrap_model(model_cls):
        return False
    if permission_input.context_ref is not None:
        return False
    scheme = permission_input.permission_shape.scheme
    if not isinstance(scheme, PermissionScheme) or isinstance(scheme, NoSecurityScheme):
        return False
    session_id = permission_input.session_id_source
    session_str = session_id_to_str(session_id)
    if is_system_or_schema_session(session_str):
        return False
    if not isinstance(session_id, SessionId):
        return lazy_runtime.scheme_policy_reads_the_session_user(
            model_cls,
            scheme,
            action=action,
        )
    if _validated_session_user_id_or_none(session_id, txn) is not None:
        return False
    return lazy_runtime.scheme_policy_reads_the_session_user(model_cls, scheme, action=action)


def get_column_masking_info(
    model_cls: type[DatabaseObjectRow],
    session_id: object,
) -> tuple[str, list[str]] | None:
    """Return any owner-based column masking metadata for lazy reads."""
    session_str = session_id_to_str(session_id)
    if _is_permission_bootstrap_model(model_cls) or is_system_or_schema_session(session_str):
        return None

    scheme = get_permission_scheme(model_cls)
    if (
        scheme is None
        or not getattr(scheme, "supports_column_visibility", False)
        or not getattr(scheme, "_column_filter_for_others", False)
    ):
        return None

    owner_field = getattr(scheme, "_owner_field", "sys_id")
    infra_fields = {
        "sys_id",
        "created_at",
        "updated_at",
        "type_id",
        "revision_id",
        "staged_commit_id",
        "deleted",
    }
    private_columns: list[str] = []
    for field_name, field_info in model_cls.model_fields.items():
        if field_name == owner_field or field_name in infra_fields:
            continue
        if get_field_visibility(model_cls, DynamicFieldName(field_name)) == ColumnVisibility.PUBLIC:
            continue
        ann = field_info.annotation
        if ann is not None and is_optional_type(ann):
            private_columns.append(field_name)
            continue
        msg = (
            f"{model_cls.__name__}.{field_name} is private but non-nullable; "
            "SelfOwnership column masking can only hide nullable private fields. "
            "Make the field nullable or use strict row filtering for this scheme."
        )
        raise PermissionCompilationError(msg)

    if not private_columns:
        return None
    return (owner_field, private_columns)


